import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BuUvxvtQ.js";const u=JSON.parse('{"title":"Shop","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/shop.md","filePath":"web-app/shop.md"}'),s={name:"web-app/shop.md"};function i(n,e,c,h,l,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="shop" tabindex="-1">Shop <a class="header-anchor" href="#shop" aria-label="Permalink to &quot;Shop&quot;">​</a></h1><p>Shop helps you find clothing for an outfit. Choose <strong>Shop</strong> in the dashboard, or follow a clothing link from a Style recommendation. Use <a href="./settings.html">Settings</a> to choose which dashboard sections you normally see.</p><h2 id="move-from-style-to-shop" tabindex="-1">Move from Style to Shop <a class="header-anchor" href="#move-from-style-to-shop" aria-label="Permalink to &quot;Move from Style to Shop&quot;">​</a></h2><p>Clothing already in your closet opens <strong>Closet</strong>, scrolls to the matching item and briefly highlights it. Other clothing opens Shop with the item name ready to edit. The latest outfit can provide context for the search.</p><p>Opening a link does not search or use an AI allowance. Edit the description, check your filters, then submit when ready. A new clothing link hides results from the previous item. <strong>Clear item context</strong> starts a fresh search.</p><h2 id="describe-what-you-need" tabindex="-1">Describe what you need <a class="header-anchor" href="#describe-what-you-need" aria-label="Permalink to &quot;Describe what you need&quot;">​</a></h2><p>Enter a clothing description, optional size/fit, clothing preference and occasion. You can set a minimum and maximum budget in the currency of your choice. Prices retain their source currency; currency conversion is unavailable. Nonmatching currencies are excluded from budget comparisons.</p><p>Shop uses the same model list and account allowance as Style. Pro and Dev accounts can supply a supported provider key or custom AI preferences. BYOK settings are shared with Style, remain in this browser, and are sent through the server only for your selected provider&#39;s request.</p><h2 id="results-and-source-availability" tabindex="-1">Results and source availability <a class="header-anchor" href="#results-and-source-availability" aria-label="Permalink to &quot;Results and source availability&quot;">​</a></h2><p>Product cards require a connected clothing source. If it is unavailable or returns no suitable items, use <strong>Direct retailer search</strong> to continue at THE ICONIC. These unavailable or empty searches do not generate an AI selection or charge usage.</p><p>Connected results show source-supplied product names, direct links, available images, prices and the time checked. AI explains why an item suits your request; it does not invent product metadata. Missing images, prices and product ratings are labelled unavailable.</p><p>Current source coverage is Australia. Check size, stock, final price, shipping and returns with the retailer before buying. Sky Style does not operate checkout or add affiliate parameters or shopping click tracking. Retailers handle purchases under their own terms.</p><p>Search descriptions and fit details go to the connected source. Preferences and candidate text go to the selected AI provider. See <a href="./security-and-privacy.html">Security &amp; Privacy</a> for data handling.</p>',13)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
